import json,os,datetime
from pathlib import Path
records=[]
for proc in sorted(Path("/proc").iterdir(),key=lambda p:int(p.name) if p.name.isdigit() else -1):
 if not proc.name.isdigit():continue
 try:
  argv=[x.decode(errors="replace") for x in (proc/"cmdline").read_bytes().split(b"\0") if x]
  if not argv or not any("python" in x.lower() or "vllm" in x.lower() for x in argv[:2]):continue
  selected=[]
  for line in (proc/"maps").read_text(errors="replace").splitlines():
   low=line.lower()
   if ".so" in low and ("/vllm/" in low or "flashmla" in low or "deep_gemm" in low or "flash_attn" in low or "_c_stable" in low):selected.append(line)
  if selected:records.append({"pid":int(proc.name),"cmdline":argv,"selected_maps":selected})
 except (OSError,ValueError) as error:records.append({"pid":int(proc.name),"error":str(error)})
print(json.dumps({"observed_utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"scope":"read-only live baseline worker native maps during GSM; stdlib only; no env read/model import/request", "processes":records},ensure_ascii=False,indent=2))
